package sheet

import "github.com/alternayte/gx/registry/icons"

props {
  // Id is the id of the dialog element. The trigger opens the sheet by this id.
  Id          string
  // Side sets the edge of the screen that the sheet slides from: Right, Left, Top or Bottom.
  Side        Side = Right
  // Title is the heading of the sheet. An empty value renders no heading.
  Title       string = ""
  // Description is the text below the title. An empty value renders no description.
  Description string = ""
  // Trigger is the element that opens the sheet on a click. A nil value renders no trigger.
  Trigger     gx.Node = nil
  // Footer is the content at the bottom of the sheet, usually the action buttons.
  Footer      gx.Node = nil
  // Open renders the sheet open on the first render.
  Open        bool = false
  // Class adds classes to the dialog element.
  Class       string = ""
  // Children is the content of the sheet.
  Children    gx.Node = nil
  // Attrs adds HTML attributes to the dialog element.
  Attrs       gx.Attrs = nil
}

<span class="contents">
  if p.Trigger != nil {
    <span data-gx-open={"#" + p.Id} class="contents">{p.Trigger}</span>
  }
  <dialog id={p.Id} open={p.Open} data-gx-dismiss data-gx-trap class={gx.Cx("fixed m-0 max-h-none max-w-none flex-col gap-4 border-border bg-background text-foreground shadow-lg outline-none open:flex transition-[translate,overlay,display] transition-discrete duration-300 ease-in-out open:duration-500 motion-reduce:transition-none backdrop:bg-black/50 backdrop:opacity-0 backdrop:transition-[opacity,overlay,display] backdrop:transition-discrete backdrop:duration-200 open:backdrop:opacity-100 starting:open:backdrop:opacity-0 motion-reduce:backdrop:transition-none", p.sideClass(), p.Class)} {...p.Attrs}>
    if p.Title != "" || p.Description != "" {
      <div class="flex flex-col gap-1.5 p-4">
        if p.Title != "" {
          <h2 class="font-semibold text-foreground">{p.Title}</h2>
        }
        if p.Description != "" {
          <p class="text-sm text-muted-foreground">{p.Description}</p>
        }
      </div>
    }
    if p.Children != nil {
      <div class="flex-1 overflow-y-auto px-4 text-sm">{p.Children}</div>
    }
    if p.Footer != nil {
      <div class="mt-auto flex flex-col gap-2 p-4">{p.Footer}</div>
    }
    <button type="button" data-gx-close class="absolute top-4 right-4 rounded-xs opacity-70 ring-offset-background transition-opacity hover:opacity-100 focus:ring-2 focus:ring-ring focus:ring-offset-2 focus:outline-hidden disabled:pointer-events-none">
      <icons.X class="size-4" />
      <span class="sr-only">Close</span>
    </button>
  </dialog>
</span>

package sheet

import (
	"github.com/alternayte/gx"
	"github.com/alternayte/gx/registry/button"
)

var SheetFixtures = gx.Fixtures[SheetProps]{
